read_and_fetch.code:
try {
  const anonKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImtvdHp4cWthZ3B0Y29rcGF2aW9sIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzY0NTAwNjMsImV4cCI6MjA5MjAyNjA2M30.hxMfM3Wll6Al9n55FORzCkGACCZijOpHmTE0VSrN_88';
  const params = new URLSearchParams(window.location.search);
  // The Join Lesson buttons across the app use a few different mechanisms: some put
  // ?lesson_id= or ?lessonId= in the URL, others store the id in the joinLessonId
  // variable before navigating. Check all three.
  const lessonId = params.get('lesson_id') || params.get('lessonId') || variables['92bf5584-1c4f-4c84-9ed8-251972e401ff'] || '';
  const token = localStorage.getItem('authToken') || sessionStorage.getItem('authToken') || '';
  if (!lessonId) {
    variables['b55dd664-6658-4b31-b636-78c566d2ccb6'] = 'No lesson specified. Please open this page from your schedule.';
    return;
  }
  if (!token) {
    variables['b55dd664-6658-4b31-b636-78c566d2ccb6'] = 'Please log in to join this lesson.';
    return;
  }
  const res = await fetch('https://kotzxqkagptcokpaviol.supabase.co/rest/v1/rpc/get_lesson_meeting_access', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey },
    body: JSON.stringify({ p_token: token, p_lesson_id: parseInt(lessonId, 10) })
  });
  if (!res.ok) {
    const errBody = await res.json().catch(() => ({}));
    variables['b55dd664-6658-4b31-b636-78c566d2ccb6'] = errBody && errBody.message ? errBody.message : 'You are not authorized to join this lesson.';
    return;
  }
  const data = await res.json();
  variables['e0acf83e-f623-4b52-aa03-85a9ce95fb52'] = data;

  // Give the browser tab a friendly title instead of the generic page name
  try {
    const otherName = data.role === 'teacher' ? data.student_name : data.teacher_name;
    wwLib.getFrontDocument().title = 'Lesson with ' + (otherName || '...');
  } catch (e) { /* noop */ }

  // Bring back whatever was drawn in an earlier session of this same lesson.
  try {
    const wbRes = await fetch('https://kotzxqkagptcokpaviol.supabase.co/rest/v1/rpc/get_lesson_whiteboard', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey },
      body: JSON.stringify({ p_token: token, p_lesson_id: parseInt(lessonId, 10) })
    });
    if (wbRes.ok) {
      const wb = await wbRes.json();
      if (wb && wb.has_state && wb.state) {
        variables['ae3b4c05-c069-4588-8f1f-91fb8d7e54a2'] = JSON.stringify(wb.state);
      }
    }
  } catch (e) { /* an empty whiteboard is fine */ }
} catch (e) {
  console.log('Failed to load meeting access', e);
  variables['b55dd664-6658-4b31-b636-78c566d2ccb6'] = 'Something went wrong loading this lesson.';
}

