const data = variables['e0acf83e-f623-4b52-aa03-85a9ce95fb52'];
const role = data?.role;
const userId = role === 'teacher' ? data?.teacher_id : data?.student_id;
const lessonId = payload?.lessonId;
const evt = payload?.event;
if (!userId || !lessonId) return;
const row = { lesson_id: parseInt(lessonId), user_id: userId, role: role, talk_seconds: payload?.localTalkSeconds || 0 };
const nowIso = new Date().toISOString();
if (evt === 'join') row.join_time = nowIso;
if (evt === 'leave') row.leave_time = nowIso;
